{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Dabrafenib, a close structural analogue sharing an aminopyrimidine and fluorinated aromatic/heteroaromatic core, has near-complete absolute oral bioavailability of 94.5% in patients, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Safinamide, a fluorobenzyl-containing drug, has an absolute oral bioavailability of 95% in healthy subjects, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Rufinamide, which contains a fluorobenzyl-triazole carboxamide motif analogous to the query's fluorobenzyl pyrazolopyridine, has oral bioavailability of 85% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C73"],
      "claim": "Meloxicam, a heteroaromatic sulfonamide drug, has an absolute oral bioavailability of 89% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Trovafloxacin, a fluorinated heteroaromatic with amino substituents, has a mean absolute oral bioavailability of 87.6% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Lemborexant, a fluorophenyl-containing heteroaromatic drug, has at least 87% oral bioavailability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Even the lowest-absorbed transferred analogue, diclofenac, has an absolute bioavailability of about 54% in humans, still well above the 20% threshold; no transferred evidence supports F < 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental analogues report absolute oral bioavailability values well above 20% (approximately 35–96%, with most >80%), and none support low bioavailability. The query's high TPSA is a physicochemical risk but is outweighed by consistent experimental evidence from structurally related drugs.",
  "evidence_gaps": [
    "No direct experimental pharmacokinetic data are available for the query molecule itself.",
    "The query's high TPSA and HBA count could affect permeability or efflux, but no transferred analogue demonstrates F < 20%.",
    "First-pass metabolism and transporter-mediated disposition of the exact query structure are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

